    if input.FeedbackGenerationRequest.Status==jevExternalApplyCapabilityReviewRevisionCandidateMaterializationAdmissionEvaluationBridgeUnknown { return unknown(input.FeedbackGenerationRequest.MissingStage) }
    prior:=input.FeedbackGenerationRequest.JEVExternalApplyCapabilityReviewRevisionCandidateMaterializationAdmissionEvaluationOutcomeFeedbackRevisionProposalBridge
    if prior.AdmissionDecision!=input.AdmissionEvaluation.AdmissionDecision { return unknown("admission-decision-consistency") }
    output:=JEVExternalApplyCapabilityReviewRevisionCandidateGenerationRequestCandidateGateRevisionProposalCandidateMaterializationAdmissionEvaluationFeedbackGenerationRequestChain{Status:jevExternalApplyCapabilityReviewRevisionCandidateGenerationRequestCandidateGateRevisionProposalCandidateMaterializationAdmissionEvaluationFeedbackGenerationRequestChainBound,AdmissionEvaluationBridgeDigest:input.AdmissionEvaluation.BridgeDigest,CandidateDecision:input.AdmissionEvaluation.CandidateDecision,RevisionProposalDigest:input.AdmissionEvaluation.RevisionProposalDigest,CandidateDigest:input.AdmissionEvaluation.CandidateDigest,CandidateSource:input.AdmissionEvaluation.CandidateSource,CandidateGateDigest:input.AdmissionEvaluation.CandidateGateDigest,MaterializationStatus:input.AdmissionEvaluation.MaterializationStatus,MaterializationBridgeDigest:input.AdmissionEvaluation.MaterializationBridgeDigest,AdmissionDecision:input.AdmissionEvaluation.AdmissionDecision,AdmissionEvaluationStatus:input.AdmissionEvaluation.EvaluationStatus,FeedbackRevisionProposalBridgeDigest:prior.BridgeDigest,FeedbackAdmissionDecision:prior.AdmissionDecision,FeedbackRevisionProposalStatus:prior.RevisionProposalStatus,FeedbackProposalDecision:prior.ProposalDecision,FeedbackProposalTarget:prior.ProposalTarget,FeedbackProposalDigest:prior.ProposalDigest,FeedbackProposalSource:prior.ProposalSource,FeedbackProposalEvidenceDigest:prior.ProposalEvidenceDigest,GenerationRequestStatus:input.FeedbackGenerationRequest.GenerationRequestStatus,GenerationRequestDigest:input.FeedbackGenerationRequest.GenerationRequestDigest,GenerationRequestSource:input.FeedbackGenerationRequest.GenerationRequestSource,GenerationRequestEvidenceDigest:input.FeedbackGenerationRequest.GenerationRequestEvidenceDigest,GeneratorIdentity:input.FeedbackGenerationRequest.GeneratorIdentity,FeedbackGenerationRequestBridgeDigest:input.FeedbackGenerationRequest.BridgeDigest,NonExecuting:true,NonAuthorizing:true}
    output.BridgeDigest=digestJEVExternalApplyCapabilityReviewRevisionCandidateGenerationRequestCandidateGateRevisionProposalCandidateMaterializationAdmissionEvaluationFeedbackGenerationRequestChain(output.Status,output.AdmissionEvaluationBridgeDigest,output.FeedbackGenerationRequestBridgeDigest,output.AdmissionDecision,output.GenerationRequestStatus,output.GenerationRequestDigest)
