func digestJEVExternalApplyCapabilityReviewRevisionCandidateGenerationRequestCandidateGateRevisionProposalCandidateMaterializationAdmissionEvaluationFeedbackGenerationRequestChain(status,admissionEvaluationBridgeDigest,feedbackGenerationRequestBridgeDigest,admissionDecision,generationRequestStatus,generationRequestDigest string) string { sum:=sha256.Sum256([]byte(strings.Join([]string{status,admissionEvaluationBridgeDigest,feedbackGenerationRequestBridgeDigest,admissionDecision,generationRequestStatus,generationRequestDigest},"|"))); return hex.EncodeToString(sum[:]) }
